customCss:
.v-app-bar .v-toolbar-title__placeholder::after { content: " 🎆"; }
.v-app-bar { border-bottom: 4px solid; border-image: linear-gradient(90deg, #B22234 33%, #FFFFFF 33% 66%, #3C3B6E 66%) 1; }

/* ✨ Twinkling stars (4th of July, or any dark theme) */
.v-application::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3000;
  background-repeat: repeat !important; /* Vuetify's reset turns repeat off */
  --star: rgba(60, 59, 110, 0.45);
  background-image:
    radial-gradient(3px 3px at 40px 60px, var(--star) 50%, transparent 51%),
    radial-gradient(4px 4px at 180px 120px, rgba(178, 34, 52, 0.5) 50%, transparent 51%),
    radial-gradient(3px 3px at 300px 40px, var(--star) 50%, transparent 51%),
    radial-gradient(5px 5px at 90px 250px, var(--star) 50%, transparent 51%),
    radial-gradient(3px 3px at 260px 300px, rgba(178, 34, 52, 0.5) 50%, transparent 51%);
  background-size: 340px 340px;
  animation: mealie-twinkle 3.5s ease-in-out infinite alternate;
}
.v-application.v-theme--dark::after { --star: rgba(255, 255, 255, 0.85); }
@keyframes mealie-twinkle {
  from { opacity: 0.25; }
  to { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .v-application::after { animation: none; }
}
